import pytest

from task_0029 import compute_scores, average, rank_top


# --------------------------------------------------------------------------
# compute_scores
# --------------------------------------------------------------------------

def test_compute_scores_maps_each_name_to_its_value():
    """A record's 'name'/'value' pair must appear as one entry in the result."""
    records = [{"name": "alice", "value": 3}, {"name": "bob", "value": 7}]
    assert compute_scores(records) == {"alice": 3, "bob": 7}


def test_compute_scores_empty_input_returns_empty_dict():
    """No records -> no scores."""
    assert compute_scores([]) == {}


def test_compute_scores_missing_name_uses_unknown_key():
    """A record without 'name' still contributes under the default key 'unknown'."""
    assert compute_scores([{"value": 5}]) == {"unknown": 5}


def test_compute_scores_missing_value_defaults_to_zero():
    """A record without 'value' contributes the value 0."""
    assert compute_scores([{"name": "carol"}]) == {"carol": 0}


def test_compute_scores_does_not_mutate_input_records():
    """The input records must be left untouched."""
    records = [{"name": "alice", "value": 3}, {"value": 1}]
    snapshot = [dict(r) for r in records]
    compute_scores(records)
    assert records == snapshot


def test_compute_scores_one_entry_per_distinct_name():
    """Result has exactly one key per distinct name.

    NOTE: the behaviour for repeated names is not specified anywhere
    (docstring/type hints/caller agreement are all silent), so only the
    structural invariant -- one key per distinct name -- is asserted here.
    """
    records = [
        {"name": "a", "value": 1},
        {"name": "a", "value": 2},
        {"name": "b", "value": 3},
    ]
    scores = compute_scores(records)
    assert set(scores) == {"a", "b"}


def test_compute_scores_returns_fresh_mapping_each_call():
    """Two calls must not share state."""
    first = compute_scores([{"name": "a", "value": 1}])
    second = compute_scores([{"name": "b", "value": 2}])
    assert first == {"a": 1}
    assert second == {"b": 2}


