@pytest.mark.parametrize(
    "scores, expected",
    [
        ({"a": 1}, 1.0),
        ({"a": 1, "b": 3}, 2.0),
        ({"a": 0, "b": 0, "c": 0}, 0.0),
        ({"a": -2, "b": 2}, 0.0),
        ({"a": 1.5, "b": 2.5}, 2.0),
        ({"a": 10, "b": 20, "c": 30}, 20.0),
        ({"a": -10, "b": -30}, -20.0),
    ],
)
def test_average_equals_arithmetic_mean(scores, expected):
    """average(scores) is the arithmetic mean of the values."""
    assert average(scores) == pytest.approx(expected)


def test_average_empty_scores_is_zero():
    """Mean of an empty collection is defined here as 0.0."""
    assert average({}) == 0.0


def test_average_returns_float_type():
    """The declared return type is float."""
    assert isinstance(average({"a": 2, "b": 4}), float)


def test_average_is_independent_of_keys():
    """Only the values matter, never the key names."""
    assert average({"x": 3, "y": 5}) == pytest.approx(average({"p": 3, "q": 5}))


def test_average_of_constant_scores_equals_that_constant():
    """Mean of n copies of v is exactly v."""
    scores = {"k{}".format(i): 7 for i in range(5)}
    assert average(scores) == pytest.approx(7.0)


def test_average_matches_sum_over_count():
    """Invariant: average == sum(values) / len(values) for non-empty input."""
    scores = {"a": 1, "b": 4, "c": 9, "d": 16}
    assert average(scores) == pytest.approx(sum(scores.values()) / len(scores))


