def test_rank_top_negative_k_returns_empty_list():
    """Top-k with a non-positive k selects nothing.

    The number of returned items must never exceed max(k, 0).  A bare
    ``items[:k]`` slice silently returns ``len(scores) - 1`` items for
    k = -1, which is not a top-k result at all and violates the contract.
