def test_rank_top_result_is_prefix_of_full_ranking():
    """The result is the prefix of the full descending ranking."""
    scores = {"a": 4, "b": 1, "c": 9, "d": 7}
    full = sorted(scores.items(), key=lambda kv: kv[1], reverse=True)
    assert rank_top(scores, 3) == full[:3]


def test_rank_top_result_length_never_exceeds_k():
